// showcase/ is read by the Home site that lists the projects. Its text is written
// by hand: these checks catch facts that drift from the code, and missing images.
// The images themselves are regenerated by scripts/update-showcase.mjs.
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { describe, it } from "node:test";
import { MODES } from "../public/bravery.js";

const file = (path) => new URL(`../${path}`, import.meta.url);
const project = readFileSync(file("showcase/project.md"), "utf8");
const roomSource = readFileSync(file("src/room.ts"), "utf8");
const constant = (name) => Number(roomSource.match(new RegExp(`export const ${name} = (\\d+);`))?.[1]);

describe("showcase", () => {
  it("references images that exist", () => {
    const paths = [...project.matchAll(/^\s*(?:cover|icon|- src|src):\s*(\S+)\s*$/gm)].map((match) => match[1]);
    assert.ok(paths.length >= 3, "cover, icon and screenshots");
    for (const path of paths) assert.ok(existsSync(file(`showcase/${path}`)), `showcase/${path} (run node scripts/update-showcase.mjs)`);
  });

  it("states the room limits of the code", () => {
    assert.ok(project.includes(`Jusqu'à ${constant("MAX_PLAYERS")} joueurs`), "MAX_PLAYERS");
    assert.ok(project.includes(`jusqu'à ${constant("MAX_BUILD_CHOICES")} builds au choix`), "MAX_BUILD_CHOICES");
    assert.ok(project.includes(`limité (jusqu'à ${constant("MAX_REROLL_LIMIT")})`), "MAX_REROLL_LIMIT");
  });

  it("names every game mode", () => {
    const labels = Object.values(MODES).map((mode) => mode.label);
    const line = project.split("\n").find((l) => l.includes("modes**")) ?? "";
    const count = { 2: "Deux", 3: "Trois", 4: "Quatre", 5: "Cinq" }[labels.length];
    assert.ok(line.includes(`**${count} modes**`), `${labels.length} modes`);
    for (const label of labels) assert.ok(line.includes(label), label);
  });
});
